//go:build goexperiment.simd && amd64

package vec

// Port-pressure probes for the Intel AVX-512 attainment gap (#104, #111).
// Generated by a throwaway script; every probe is register-resident apart from
// the loads it names, and each FMA adds exactly 1 to its accumulator, so
// TestPortProbeWitness can check that no chain was merged (T8).
//
//	acc/N=n          E1: n independent peak-form chains (acc = acc*y + x, no copies).
//	pf/ld/k=k        E2: 8 peak-form chains, k broadcasts per 8 FMAs, each from a
//	                 scalar load (VMOVSS m32 + VBROADCASTSS zmm,xmm: the kernel's form).
//	pf/reg/k=k       E2: same, the scalar already in a register (no load in the loop).
//	pf/pre/k=k       E2: same, the multiplicand a 64-byte load of a pre-broadcast panel.
//	pf/mix/{ld,pre}  the kernel's per-k-step mix (2 B loads, 4 A broadcasts, 8 FMAs)
//	                 with the accumulator in the multiplicand slot: no copy-back.
//	kf/mix/{ld,pre}  the same mix written as the kernel writes it (acc = av*b + acc).
//	kf/k=0           kernel-form FMAs on loop-invariant operands: the copy-back alone.
//
// Loads go through two pointers swapped every iteration because go1.27.3 hoists a
// constant-address load out of the loop; a broadcast of a loop-invariant scalar
// is not hoisted (golang/go#79984), which is what pf/reg relies on. Bodies call
// archsimd directly, not the hot-layer wrappers, so they carry no inline-mark NOPs.
//
// Steady-state loop mix, go1.27.3 objdump, linux/amd64. p05 counts the 512-bit
// vector-ALU uops (FMA, VBROADCASTSS zmm,xmm, VMOVDQU64 zmm,zmm); the "Intel"
// column is the ceiling predicted BEFORE any run by the hypothesis under test:
// on Skylake-X/SPR/GNR every one of them needs port 0 or 5, and the two FMA ports
// are the same two ports, so attainment <= FMAs/p05 of the 2-FMA/cycle peak.
//
//	probe        insns FMA bcast(reg) zmm-copy loads  p05  Intel ceiling
//	kernel/4x32    50   8     4         12     2+4    24   33.3%
//	kernel/2x32    75  16     8          8     8+8    32   50.0% (and 4 chains x 4 deep)
//	kf/mix/ld      39   8     4         12     2+4    24   33.3%  kernel mix, no slice guards
//	kf/mix/pre     32   8     0         12     6      20   40.0%
//	kf/k=0         28   8     0         17     0      25   32.0%
//	pf/mix/ld      27   8     4          0     2+4    12   66.7%  no copy-back (231-like)
//	pf/mix/pre     20   8     0          0     6       8  100%
//	pf/ld/k=1,2,4  16-22 8  1,2,4        0     k       9-12 88.9/80/66.7%
//	pf/reg/k=1,2,4 13-19 8  1,2,4        0     0       9-12 88.9/80/66.7%
//	pf/pre/k=1,2,4 15-18 8    0          0     k       8  100%
//	acc/N=n        28-43 24-40 0         0     0     =FMA  min(1, n/8) at latency 4
//
// Zen 4/5 execute the copies (move elimination) and broadcasts off their FMA
// pipes, so the same rows there should sit near 100% wherever the FMA chains
// alone allow it.
//
// MEASURED, and it overrules parts of the table above. Exploration tier,
// unjudged, 2026-10-25, one thread pinned to CPU 0, 5 interleaved passes,
// median percent of the same pass's acc/N=12 rate (the clean 2-FMA/cycle
// ceiling; janus i9-9960X 233.7, c7i.4xlarge Xeon 8488C 228.6, c8i.4xlarge
// Xeon 6975P-C 235.8, c8a.4xlarge EPYC 9R45 286.6 GFLOP/s):
//
//	row                  janus  SPR   GNR   Zen5
//	acc/N=8              100.1  90.8  92.5  96.2   8 chains: short of peak on SPR/GNR
//	pf/reg/k=1,2,4       84/75/62  84/75/61  85/76/64  94/94/78
//	pf/pre/k=4            94.1  81.9  77.2  96.2
//	pf/mix/ld             61.5  62.6  60.6  82.2
//	pf/mix/pre            80.0  86.2  72.6  99.8
//	kf/mix/ld             42.1  62.2  59.8  70.0   copy-back: costly on janus only
//	kernel/4x32 (const)   32.4  49.5  49.3  65.3
//
// The register-source broadcast rows match the port-0/5 prediction on all three
// Intel parts. The copy-back rows do not on SPR/GNR: there the 12 zmm copies cost
// about nothing (kf/mix/ld = pf/mix/ld), so 33.3% was the right prediction for
// janus only. kernel/4x32 sits ~12 points under kf/mix/ld on SPR/GNR, which is
// the slice-advance arithmetic the probe omits.

import (
	"fmt"
	"math/rand"
	"simd/archsimd"
	"testing"
	"unsafe"
)

// The panels are 64-byte aligned on purpose. As plain globals the linker put
// probeV at 32 mod 64, so every 64-byte load split a cache line, and on janus the
// pre-broadcast rows read exactly the ceiling of twice their load count.
var (
	probeS *[4][64]float32
	probeV *[4][32][16]float32
)

// alignedF32 returns n float32s starting on a 64-byte boundary.
func alignedF32(n int) []float32 {
	s := make([]float32, n+16)
	off := (16 - int(uintptr(unsafe.Pointer(&s[0]))%64)/4) % 16
	return s[off : off+n]
}

func init() {
	probeS = (*[4][64]float32)(unsafe.Pointer(&alignedF32(4 * 64)[0]))
	probeV = (*[4][32][16]float32)(unsafe.Pointer(&alignedF32(4 * 32 * 16)[0]))
	for p := range probeS {
		for i := range probeS[p] {
			probeS[p][i] = 1
		}
	}
	for p := range probeV {
		for i := range probeV[p] {
			for j := range probeV[p][i] {
				probeV[p][i][j] = 1
			}
		}
	}
}

type portProbe struct {
	name string
	accs int
	fmas int // FMAs per loop iteration
	run  func(iters int) float32
}

//go:noinline
func probe_acc_N4(iters int) float32 {
	x := Broadcast512(peakOne())
	y := Broadcast512(peakOne())
	_, _ = x, y
	a0 := Broadcast512(1)
	a1 := Broadcast512(2)
	a2 := Broadcast512(3)
	a3 := Broadcast512(4)
	for i := 0; i < iters; i++ {
		a0 = a0.MulAdd(y, x)
		a1 = a1.MulAdd(y, x)
		a2 = a2.MulAdd(y, x)
		a3 = a3.MulAdd(y, x)
		a0 = a0.MulAdd(y, x)
		a1 = a1.MulAdd(y, x)
		a2 = a2.MulAdd(y, x)
		a3 = a3.MulAdd(y, x)
		a0 = a0.MulAdd(y, x)
		a1 = a1.MulAdd(y, x)
		a2 = a2.MulAdd(y, x)
		a3 = a3.MulAdd(y, x)
		a0 = a0.MulAdd(y, x)
		a1 = a1.MulAdd(y, x)
		a2 = a2.MulAdd(y, x)
		a3 = a3.MulAdd(y, x)
		a0 = a0.MulAdd(y, x)
		a1 = a1.MulAdd(y, x)
		a2 = a2.MulAdd(y, x)
		a3 = a3.MulAdd(y, x)
		a0 = a0.MulAdd(y, x)
		a1 = a1.MulAdd(y, x)
		a2 = a2.MulAdd(y, x)
		a3 = a3.MulAdd(y, x)
	}
	return HSum512(Add512(Add512(a0, a1), Add512(a2, a3)))
}

