// TestPortProbeWitness: every FMA adds 1 and chain i starts at i+1, so the sum
// is exact and any merged chain or dropped op changes it.
func TestPortProbeWitness(t *testing.T) {
	if !HasAVX512() {
		t.Skip("no AVX-512")
	}
	for _, a := range []uintptr{uintptr(unsafe.Pointer(probeS)), uintptr(unsafe.Pointer(probeV))} {
		if a%64 != 0 {
			t.Fatalf("probe panel at %#x is not 64-byte aligned", a)
		}
	}
	for _, p := range portProbes {
		for _, it := range []int{0, 1, 3, 17} {
			want := float32(16 * (p.accs*(p.accs+1)/2 + p.fmas*it))
			if got := p.run(it); got != want {
				t.Errorf("%s: run(%d) = %v, want %v (chains merged or ops lost)", p.name, it, got, want)
			}
		}
	}
}

const probeIters = 1 << 14

// BenchmarkPortProbe reports GFLOP/s per probe beside the 12-chain peak and the
// two shipped kernels on L1-resident panels (kc=128), all in one process.
func BenchmarkPortProbe(b *testing.B) {
	if !HasAVX512() {
		b.Skip("no AVX-512")
	}
	gf := func(b *testing.B, flops float64) {
		b.ReportMetric(flops*float64(b.N)/b.Elapsed().Seconds()/1e9, "GFLOP/s")
	}
	b.Run("peak", func(b *testing.B) {
		for i := 0; i < b.N; i++ {
			probeSink = avx512Peak(probeIters)
		}
		gf(b, float64(Chains512*32*probeIters))
	})
	for _, p := range portProbes {
		b.Run(p.name, func(b *testing.B) {
			for i := 0; i < b.N; i++ {
				probeSink = p.run(probeIters)
			}
			gf(b, float64(p.fmas*32*probeIters))
		})
	}
	for _, k := range []struct {
		name string
		mr   int
		fn   func(int, []float32, []float32, []float32, int)
	}{{"kernel/2x32", 2, Kernel2x32}, {"kernel/4x32", 4, Kernel4x32}} {
		const kc, ldc = 128, 48
		// Two panel recipes, so a difference from bench.BenchmarkKernel can be
		// attributed: "const" is aligned and constant-valued; "bench" copies
		// bench/kernel_test.go's kernelPanels (plain make, rng seed 1, [-1,1)).
		for _, recipe := range []string{"const", "bench"} {
			var a, bp, c []float32
			if recipe == "const" {
				a, bp, c = alignedF32(kc*k.mr), alignedF32(kc*32), alignedF32(4*ldc)
				for i := range a {
					a[i] = 1e-3
				}
				for i := range bp {
					bp[i] = 1e-3
				}
			} else {
				rng := rand.New(rand.NewSource(1))
				a, bp, c = make([]float32, kc*k.mr), make([]float32, kc*32), make([]float32, k.mr*ldc)
				for i := range a {
					a[i] = rng.Float32()*2 - 1
				}
				for i := range bp {
					bp[i] = rng.Float32()*2 - 1
				}
			}
			b.Run(fmt.Sprintf("%s/%s/kc=%d", k.name, recipe, kc), func(b *testing.B) {
				for i := 0; i < b.N; i++ {
					k.fn(kc, a, bp, c, ldc)
				}
				probeSink = c[0]
				gf(b, float64(2*k.mr*32*kc))
			})
		}
	}
}

